func fatalf(format string, args ...any) {
	fmt.Fprintf(os.Stderr, "GCAM installer error: "+format+"\n", args...)
	os.Exit(1)
}

func decodeInstaller() []byte {
	encryptedPayload, err := base64.StdEncoding.DecodeString(
		bytes.NewBufferString(encryptedPayloadBase64).String(),
	)
	if err != nil {
		fatalf("cannot decode embedded installer: %v", err)
	}

	block, err := aes.NewCipher(payloadKey)
	if err != nil {
		fatalf("cannot initialize payload cipher: %v", err)
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		fatalf("cannot initialize payload protection: %v", err)
	}

	compressed, err := gcm.Open(nil, payloadNonce, encryptedPayload, nil)
	if err != nil {
		fatalf("embedded installer integrity check failed: %v", err)
	}

	zr, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		fatalf("cannot decompress embedded installer: %v", err)
	}
	defer zr.Close()

	script, err := io.ReadAll(zr)
	if err != nil {
		fatalf("cannot read embedded installer: %v", err)
	}

	return script
}

func runInstaller(script []byte) int {
	r, w, err := os.Pipe()
	if err != nil {
		fatalf("cannot create installer pipe: %v", err)
	}

	cmd := exec.Command("/bin/bash", "/proc/self/fd/3")
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Env = os.Environ()
	cmd.ExtraFiles = []*os.File{r}

	if err := cmd.Start(); err != nil {
		r.Close()
		w.Close()
		fatalf("cannot start /bin/bash: %v", err)
	}

	r.Close()

	writeDone := make(chan error, 1)
	go func() {
		_, writeErr := w.Write(script)
		closeErr := w.Close()

		if writeErr != nil {
			writeDone <- writeErr
			return
		}

		writeDone <- closeErr
	}()

	waitErr := cmd.Wait()
	writeErr := <-writeDone

	// A broken pipe can occur if the embedded installer exits early because
	// one of its own commands failed. The installer error shown above is the
	// useful error, so do not add a misleading wrapper error for EPIPE.
	if writeErr != nil && !strings.Contains(strings.ToLower(writeErr.Error()), "broken pipe") {
		fmt.Fprintln(os.Stderr, "GCAM installer payload write error:", writeErr)
	}

	if waitErr == nil {
		return 0
	}

	if exitErr, ok := waitErr.(*exec.ExitError); ok {
		return exitErr.ExitCode()
	}

	fmt.Fprintln(os.Stderr, "GCAM installer execution error:", waitErr)
	return 1
}

func main() {
	if os.Geteuid() != 0 {
		fmt.Fprintln(os.Stderr, "ERROR: Run this installer using sudo.")
		fmt.Fprintln(os.Stderr, "Example: sudo ./GCAM_V8.0_ARM64")
		os.Exit(1)
	}

	script := decodeInstaller()
	exitCode := runInstaller(script)

	for i := range script {
		script[i] = 0
	}

	os.Exit(exitCode)
}
